import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.DC2anBTf.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md","lastUpdated":1793538094000}'),i={name:"en/guide/faq.md"};function r(s,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="the-redirect-parameter-is-double-encoded-on-web-252f" tabindex="-1">The redirect parameter is double-encoded on Web (<code>%252F</code>)? <a class="header-anchor" href="#the-redirect-parameter-is-double-encoded-on-web-252f" aria-label="Permalink to &quot;The redirect parameter is double-encoded on Web (`%252F`)?&quot;">​</a></h2><p>Known behavior. The round-trip is correct (guard registration and return-jump restoration match); verify on a real device before shipping to Android for deep-link scenarios.</p><h2 id="the-console-shows-navigationfailure-logs" tabindex="-1">The console shows <code>NavigationFailure</code> logs? <a class="header-anchor" href="#the-console-shows-navigationfailure-logs" aria-label="Permalink to &quot;The console shows `NavigationFailure` logs?&quot;">​</a></h2><p>Known ux-router behavior on Web (a confirmation log after relaunch); the navigation result is correct and <strong>should not be treated as an error</strong>.</p><h2 id="why-not-standard-pinia-for-state-management" tabindex="-1">Why not standard Pinia for state management? <a class="header-anchor" href="#why-not-standard-pinia-for-state-management" aria-label="Permalink to &quot;Why not standard Pinia for state management?&quot;">​</a></h2><p>uni-app x&#39;s App side (Kotlin) does not support standard Pinia&#39;s plugin protocol (<code>app.use</code> verified not to work), and UTS has no Proxy and no reflection, making standard Pinia&#39;s reactivity model impossible to implement. ux-pinia implements a Pinia-style API within UTS using a class + reactive architecture (see the &quot;Differences from Standard Pinia&quot; chapter in the <a href="https://mengxi-studio.github.io/unix-pinia/" target="_blank" rel="noreferrer">unix-pinia docs</a>).</p><h2 id="why-doesn-t-the-token-use-ux-pinia-s-built-in-persistence-plugin" tabindex="-1">Why doesn&#39;t the token use ux-pinia&#39;s built-in persistence plugin? <a class="header-anchor" href="#why-doesn-t-the-token-use-ux-pinia-s-built-in-persistence-plugin" aria-label="Permalink to &quot;Why doesn&#39;t the token use ux-pinia&#39;s built-in persistence plugin?&quot;">​</a></h2><p>Separation of concerns: token read/write is consolidated in <code>utils/auth.uts</code> (mirroring js-cookie&#39;s responsibility), and the <code>ensureAuthReady()</code> cold-start race elimination design is verified end to end; the built-in persistence defaults to uni storage, and coexisting with ux-storage would split persistence semantics. The built-in persistence is reserved for business-state scenarios (such as drafts).</p><h2 id="ux-storage-is-asynchronous-—-why-is-reading-the-token-synchronous" tabindex="-1">ux-storage is asynchronous — why is reading the token synchronous? <a class="header-anchor" href="#ux-storage-is-asynchronous-—-why-is-reading-the-token-synchronous" aria-label="Permalink to &quot;ux-storage is asynchronous — why is reading the token synchronous?&quot;">​</a></h2><p>Smoothed by an in-memory cache: writes take effect in memory immediately and persist asynchronously; at cold start the first line of the guard chain, <code>await ensureAuthReady()</code>, restores the memory cache once (Promise reuse, no races). See <a href="./auth.html">Auth &amp; Guards</a>.</p><h2 id="release-packaging-cloud-packaging-release-to-web-fails-but-dev-works" tabindex="-1">Release packaging (cloud packaging / release to Web) fails, but dev works? <a class="header-anchor" href="#release-packaging-cloud-packaging-release-to-web-fails-but-dev-works" aria-label="Permalink to &quot;Release packaging (cloud packaging / release to Web) fails, but dev works?&quot;">​</a></h2><p>Pitfalls caused by differences between the release pipeline and dev have been fixed in the template (verified on 5.34):</p><ul><li>UTS plugin entry points <strong>must not export string constants</strong> (uts-proxy generates invalid JS);</li><li>Domain types must be defined within the single <code>&lt;domain&gt;/types.uts</code> file (release builds do not follow <code>export type ... from</code> forwarding chains);</li><li>Inside plugin components, avoid <code>Animation</code> type annotations, script-level <code>slots.default</code> checks, and <code>watch</code> with <code>flush</code> (Unresolved in the 5.34 Kotlin generator).</li></ul><p>See the Fixed section of CHANGELOG 1.1.0 in the repository.</p><h2 id="android-cannot-connect-to-the-local-mock" tabindex="-1">Android cannot connect to the local mock? <a class="header-anchor" href="#android-cannot-connect-to-the-local-mock" aria-label="Permalink to &quot;Android cannot connect to the local mock?&quot;">​</a></h2><p><code>127.0.0.1</code> on a real device points to the phone itself. Change <code>baseURL</code> in <code>config/index.uts</code> to the computer&#39;s LAN IP (e.g. <code>http://192.168.x.x:3210</code>), keep the phone and computer on the same network, and make the mock service listen on <code>0.0.0.0</code>.</p><h2 id="guards-don-t-take-effect-after-navigating-to-a-new-page" tabindex="-1">Guards don&#39;t take effect after navigating to a new page? <a class="header-anchor" href="#guards-don-t-take-effect-after-navigating-to-a-new-page" aria-label="Permalink to &quot;Guards don&#39;t take effect after navigating to a new page?&quot;">​</a></h2><p>Check two things: the page declares the <code>defineUniPage({ name, title })</code> macro (the route table is generated by the plugin); navigation goes through <code>useRouter()</code> rather than the <code>uni.navigateTo</code> family (the latter is intercepted by the InterceptorPlugin fallback, but the fallback must not be relied upon).</p><h2 id="are-there-hbuilderx-version-requirements" tabindex="-1">Are there HBuilderX version requirements? <a class="header-anchor" href="#are-there-hbuilderx-version-requirements" aria-label="Permalink to &quot;Are there HBuilderX version requirements?&quot;">​</a></h2><p>The template completed compilation and packaging verification on <strong>5.34</strong> (Web + Android cloud packaging). Earlier versions are unverified; newer versions require attention to UTS compiler behavior changes.</p>',21)])])}const g=a(i,[["render",r]]);export{p as __pageData,g as default};
